/**
 * Review sheets of the robed cultists' round 2 (bead pulp_wars-mch9.54):
 * ordinary people in evil robes with bloody daggers. It makes no PixelLab
 * call: the variants are generated by the chibi pipeline's exploration runs
 * under `art/explorations/cult-sprites-mch954/<variant>/` (`npm run
 * art:chibi -- generate --exploration <run> --ids …`), the chosen pieces are
 * imported into batches `direction-cult` and `interface-cult`, and this
 * script only draws them.
 *
 * "Before" is the round-1 production look, re-derived from the superseded
 * production recipes' recorded candidates through their accent preset, so
 * no copy of the old masters is kept.
 *
 *   tsx scripts/art/cult-sprites-mch954/review.ts candidates --run DIR --out FILE.png
 *       every candidate of the run, with its asset's accent applied, at x4
 *       and 1x on the Cult's bog ground, with its green and red shares
 *   tsx scripts/art/cult-sprites-mch954/review.ts sheet (--run DIR | --production) --title TEXT --out FILE.png
 *       before and after on the bog at 1x, the new set x3, the busts before
 *       and after at x1 and x3 (production only), and a board mock (a Cult
 *       city, three faded Cult buildings, the five cultists, three summons,
 *       Undead and Human units) at 1x and x2
 *   tsx scripts/art/cult-sprites-mch954/review.ts compare --out FILE.png RUN…
 *       the round-1 five and each run's five in rows, at 1x and x2
 */
import { readFile } from "node:fs/promises";
import path from "node:path";
import process from "node:process";
import {
  BUILDING_FADE_GROUNDS_V7,
  BUILDING_FADE_V7,
  fadeBuildingPixelsV7,
} from "../../../src/render/canvas/building-fade-v7";
import { accentPreset, accentRaster } from "../chibi/accent";
import type { ChibiBatchManifest } from "../chibi/batch-manifest";
import { rgbToHsv, type RgbaRaster } from "../chibi/owner-mask";
import {
  loadRecords,
  explorationLayout,
  productionLayout,
  readRaster,
} from "../chibi/pipeline";
import { candidateCell, cropRaster } from "../chibi/raster";
import type { Rgb } from "../ice-folk-direction/colour";
import {
  blank,
  blit,
  writeSheet,
  type Canvas,
  type Label,
} from "../ice-folk-direction/raster-tools";

const ROOT = process.cwd();
const BG: Rgb = [30, 32, 36];
const CELL = 80;
const UNITS = "public/assets/chibi/units";
const PORTRAITS = "public/assets/chibi/portraits";

/**
 * The five robed cultists of the redesigned roster, in roster order, with
 * the round-1 recipes (batch `direction-cult` and `interface-cult`, the
 * `cult-lodge` and `cult-lodge-icon` accents) that round 2 superseded.
 */
export const ROBED_ROLES = [
  {
    role: "FIGHTER",
    name: "Initiate",
    current: "initiate",
    before: "initiate-a-indigo-flop",
    beforePortrait: "portrait-initiate-b-eyes",
  },
  {
    role: "GUARD",
    name: "Idol Bearer",
    current: "idol-bearer",
    before: "idol-bearer-s-one",
    beforePortrait: "portrait-idol-bearer-s",
  },
  {
    role: "MARKSMAN",
    name: "Hexer",
    current: "hexer",
    before: "hexer-s",
    beforePortrait: "portrait-hexer-s",
  },
  {
    role: "CAPTAIN",
    name: "Summoner",
    current: "summoner",
    before: "summoner-s",
    beforePortrait: "portrait-summoner-s",
  },
  {
    role: "CATAPULT",
    name: "Stargazer",
    current: "stargazer",
    before: "stargazer-a-hood",
    beforePortrait: "portrait-stargazer-s",
  },
] as const;

function option(name: string): string | undefined {
  const index = process.argv.indexOf(name);
  return index < 0 ? undefined : process.argv[index + 1];
}

function required(name: string): string {
  const value = option(name);
  if (value === undefined) throw new Error(`${name} is required`);
  return value;
}

const load = (file: string): Promise<RgbaRaster> =>
  readRaster(path.isAbsolute(file) ? file : path.join(ROOT, file));

async function manifestOf(run: string): Promise<ChibiBatchManifest> {
  return JSON.parse(
    await readFile(path.join(ROOT, run, "batch.json"), "utf8"),
  ) as ChibiBatchManifest;
}

/** Tiles the bog (the six Cult grounds in turn) over a cell grid. */
async function bogTiles(): Promise<RgbaRaster[]> {
  const tiles: RgbaRaster[] = [];
  for (let k = 1; k <= 6; k += 1)
    tiles.push(
      await load(
        `public/assets/chibi/terrain/faction-grass/chibi-cult-grass-${k}.png`,
      ),
    );
  return tiles;
}

/** A sprite bottom-centred on a cell whose top-left is (left, top). */
function place(
  canvas: Canvas,
  sprite: RgbaRaster,
  left: number,
  top: number,
  scale: number,
): void {
  blit(
    canvas,
    sprite,
    left + Math.floor(((CELL - sprite.width) * scale) / 2),
    top + (CELL - sprite.height) * scale,
    scale,
  );
}

function faded(sprite: RgbaRaster): RgbaRaster {
  if (BUILDING_FADE_V7 === null) return sprite;
  return {
    width: sprite.width,
    height: sprite.height,
    data: new Uint8Array(
      fadeBuildingPixelsV7(new Uint8ClampedArray(sprite.data), {
        strength: BUILDING_FADE_V7,
        ground: BUILDING_FADE_GROUNDS_V7.CULT,
      }),
    ),
  };
}

/** Shares of the opaque pixels: faction green, saturated red, skin-ish. */
function shares(sprite: RgbaRaster): { green: number; red: number } {
  let opaque = 0;
  let green = 0;
  let red = 0;
  for (let index = 0; index < sprite.width * sprite.height; index += 1) {
    if ((sprite.data[index * 4 + 3] ?? 0) < 128) continue;
    opaque += 1;
    const p = rgbToHsv(
      sprite.data[index * 4] ?? 0,
      sprite.data[index * 4 + 1] ?? 0,
      sprite.data[index * 4 + 2] ?? 0,
    );
    if (p.hue >= 80 && p.hue <= 152 && p.saturation >= 0.5 && p.value >= 0.45)
      green += 1;
    if ((p.hue >= 345 || p.hue <= 12) && p.saturation >= 0.5 && p.value >= 0.3)
      red += 1;
  }
  return { green: green / opaque, red: red / opaque };
}

/** A recorded candidate of a production batch with its asset's accent. */
async function recordedCandidate(
  batch: string,
  recipeId: string,
  k = 0,
): Promise<RgbaRaster> {
  const records = await loadRecords(productionLayout(ROOT, batch), batch);
  const record = records.recipes[recipeId];
  if (record?.rawSheet === undefined || record.candidateSize === undefined)
    throw new Error(`${batch}/${recipeId}: no raw sheet`);
  const raw = cropRaster(await load(record.rawSheet), {
    ...candidateCell(k, record.candidateCount ?? 1, record.candidateSize),
    ...record.candidateSize,
  });
  // The round-1 recipes were accepted with the lodge's presets.
  const preset = batch === "interface-cult" ? "cult-lodge-icon" : "cult-lodge";
  const spec = accentPreset(preset);
  return spec === undefined ? raw : accentRaster(raw, spec).raster;
}

const beforeSprites = (): Promise<RgbaRaster[]> =>
  Promise.all(
    ROBED_ROLES.map((entry) =>
      recordedCandidate("direction-cult", entry.before),
    ),
  );

const beforePortraits = (): Promise<RgbaRaster[]> =>
  Promise.all(
    ROBED_ROLES.map((entry) =>
      recordedCandidate("interface-cult", entry.beforePortrait),
    ),
  );

async function candidates(run: string, out: string): Promise<void> {
  const manifest = await manifestOf(run);
  const records = await loadRecords(
    explorationLayout(ROOT, run),
    manifest.batch,
  );
  const bog = await bogTiles();
  const items: { label: string; sprite: RgbaRaster }[] = [];
  const only = option("--ids")?.split(",");
  for (const recipe of manifest.recipes) {
    if (only !== undefined && !only.includes(recipe.id)) continue;
    const record = records.recipes[recipe.id];
    if (record?.rawSheet === undefined || record.candidateSize === undefined)
      continue;
    const asset = manifest.assets.find((a) => a.id === recipe.asset);
    const spec =
      asset?.accent === undefined ? undefined : accentPreset(asset.accent);
    const sheet = await load(record.rawSheet);
    const count = record.candidateCount ?? 1;
    for (let k = 0; k < count; k += 1) {
      const raw = cropRaster(sheet, {
        ...candidateCell(k, count, record.candidateSize),
        ...record.candidateSize,
      });
      const sprite = spec === undefined ? raw : accentRaster(raw, spec).raster;
      const measured = shares(sprite);
      items.push({
        label: `${recipe.id}.${k}${record.review === undefined ? "" : ` ${record.review.verdict === "ACCEPTED" && record.review.candidate === k ? "ACC" : "rej"}`} g${(measured.green * 100).toFixed(1)} r${(measured.red * 100).toFixed(0)}`,
        sprite,
      });
    }
  }
  const columns = Math.min(6, items.length);
  const rows = Math.ceil(items.length / columns);
  const blockW = CELL * 4 + 16;
  const blockH = 24 + 96 * 4 + 8 + 96 + 16;
  const canvas = blank(columns * blockW + 16, rows * blockH + 16, BG);
  const labels: Label[] = [];
  items.forEach((item, index) => {
    const left = 8 + (index % columns) * blockW;
    const top = 8 + Math.floor(index / columns) * blockH;
    labels.push({ text: item.label, left, top, size: 13 });
    const tile = bog[index % bog.length] as RgbaRaster;
    blit(canvas, tile, left, top + 24 + 16 * 4, 4);
    place(canvas, item.sprite, left, top + 24 + 16 * 4, 4);
    blit(canvas, tile, left, top + 24 + 96 * 4 + 8 + 16);
    place(canvas, item.sprite, left, top + 24 + 96 * 4 + 8 + 16, 1);
  });
  await writeSheet(path.resolve(ROOT, out), canvas, labels);
}

/** The new five: a run's accepted samples or the production masters. */
async function newSprites(run: string | undefined): Promise<RgbaRaster[]> {
  if (run === undefined)
    return Promise.all(
      ROBED_ROLES.map((entry) =>
        load(`${UNITS}/chibi-direction-cult-${entry.current}.png`),
      ),
    );
  const manifest = await manifestOf(run);
  const sprites: RgbaRaster[] = [];
  for (const entry of ROBED_ROLES) {
    const asset = manifest.assets.find((a) => a.subject.endsWith(entry.role));
    if (asset === undefined) throw new Error(`no asset for ${entry.role}`);
    // A role with no accepted sample (variant B's Summoner) stays empty.
    sprites.push(
      await load(path.join(run, "assets", "units", `${asset.id}.png`)).catch(
        () => ({ width: 1, height: 1, data: new Uint8Array(4) }),
      ),
    );
  }
  return sprites;
}

async function sheet(
  run: string | undefined,
  title: string,
  out: string,
): Promise<void> {
  const bog = await bogTiles();
  const grass = await load("public/assets/chibi/terrain/chibi-grass-1.png");
  const samples = await newSprites(run);
  const before = await beforeSprites();
  const portraits =
    run === undefined
      ? {
          before: await beforePortraits(),
          after: await Promise.all(
            ROBED_ROLES.map((entry) =>
              load(
                `${PORTRAITS}/chibi-direction-portrait-cult-${entry.current}.png`,
              ),
            ),
          ),
        }
      : undefined;
  const labels: Label[] = [];
  const pairW = CELL * 2 + 4;
  const gap = 20;
  const s1Top = 40;
  const s2Top = s1Top + 22 + 24 + CELL + 24;
  const s2H = 22 + 24 + CELL * 3;
  // Busts: before | after at 1x, then x3 (production only).
  const sPTop = s2Top + s2H + 24;
  const sPH = portraits === undefined ? 0 : 22 + 24 + 48 * 3 + 24;
  const boardCols = 11;
  const boardRows = 3;
  const s3Top = sPTop + sPH;
  const s3H = 22 + boardRows * CELL + 16 + 22 + boardRows * CELL * 2;
  const width = Math.max(
    16 + ROBED_ROLES.length * (pairW + gap),
    16 + ROBED_ROLES.length * CELL * 3 + 4 * 12,
    16 + boardCols * CELL * 2,
  );
  const canvas = blank(width, s3Top + s3H + 12, BG);
  labels.push({ text: title, left: 8, top: 8, size: 18 });
  labels.push({
    text: "In-game size (1x) on the Cult bog: before (round 1) | after",
    left: 8,
    top: s1Top,
    size: 13,
    fill: "#a9b0b8",
  });
  ROBED_ROLES.forEach((entry, index) => {
    const left = 8 + index * (pairW + gap);
    const top = s1Top + 22 + 24;
    labels.push({ text: entry.name, left, top: s1Top + 22, size: 13 });
    blit(canvas, bog[index % 6] as RgbaRaster, left, top);
    blit(canvas, bog[(index + 3) % 6] as RgbaRaster, left + CELL + 4, top);
    place(canvas, before[index] as RgbaRaster, left, top, 1);
    place(canvas, samples[index] as RgbaRaster, left + CELL + 4, top, 1);
  });
  labels.push({
    text: "After, enlarged x3",
    left: 8,
    top: s2Top,
    size: 13,
    fill: "#a9b0b8",
  });
  ROBED_ROLES.forEach((entry, index) => {
    const left = 8 + index * (CELL * 3 + 12);
    const top = s2Top + 22 + 24;
    labels.push({ text: entry.name, left, top: s2Top + 22, size: 13 });
    blit(canvas, bog[(index + 1) % 6] as RgbaRaster, left, top, 3);
    place(canvas, samples[index] as RgbaRaster, left, top, 3);
  });
  if (portraits !== undefined) {
    labels.push({
      text: "Portraits (the Initiate's is the faction emblem): before | after at 1x, then after x2",
      left: 8,
      top: sPTop,
      size: 13,
      fill: "#a9b0b8",
    });
    const panel: Rgb = [58, 62, 70];
    ROBED_ROLES.forEach((entry, index) => {
      const left = 8 + index * (48 * 6 + 20 + 12) * 0.62;
      const top = sPTop + 22 + 24;
      labels.push({ text: entry.name, left, top: sPTop + 22, size: 13 });
      blit(canvas, blank(48 * 2 + 4, 48, panel), left, top);
      blit(canvas, portraits.before[index] as RgbaRaster, left, top);
      blit(canvas, portraits.after[index] as RgbaRaster, left + 52, top);
      blit(canvas, blank(48 * 2, 48 * 2, panel), left, top + 52);
      blit(canvas, portraits.after[index] as RgbaRaster, left, top + 52, 2);
    });
  }
  // The board: columns 0-7 Cult bog, 8-10 default Grass (Human units).
  const board = blank(boardCols * CELL, boardRows * CELL, BG);
  for (let y = 0; y < boardRows; y += 1)
    for (let x = 0; x < boardCols; x += 1)
      blit(
        board,
        x < 8 ? (bog[(x * 5 + y * 3) % 6] as RgbaRaster) : grass,
        x * CELL,
        y * CELL,
      );
  const at = (sprite: RgbaRaster, x: number, y: number): void =>
    place(board, sprite, x * CELL, y * CELL, 1);
  const building = async (name: string): Promise<RgbaRaster> =>
    faded(await load(`public/assets/chibi/buildings/chibi-cult-${name}.png`));
  const city = await load(
    "public/assets/chibi/settlements/chibi-direction-cult-city-2.png",
  );
  // Back row first, so nearer rows overlap it as on the board.
  at(await building("sawmill"), 0, 0);
  at(city, 1, 0);
  at(await building("workshop"), 2, 0);
  at(samples[3] as RgbaRaster, 3, 0);
  at(await load(`${UNITS}/chibi-direction-cult-imp.png`), 4, 0);
  at(await building("market"), 5, 0);
  at(await load(`${UNITS}/chibi-direction-undead-necromancer.png`), 7, 0);
  at(samples[4] as RgbaRaster, 0, 1);
  at(samples[1] as RgbaRaster, 2, 1);
  at(samples[0] as RgbaRaster, 3, 1);
  at(await load(`${UNITS}/chibi-direction-cult-horror.png`), 5, 1);
  at(await load(`${UNITS}/chibi-direction-undead-skeleton.png`), 7, 1);
  at(samples[0] as RgbaRaster, 1, 2);
  at(samples[2] as RgbaRaster, 2, 2);
  at(await load(`${UNITS}/chibi-direction-cult-mass.png`), 4, 2);
  at(await load(`${UNITS}/chibi-direction-fighter.png`), 8, 1);
  at(await load(`${UNITS}/chibi-direction-knight.png`), 9, 0);
  at(await load(`${UNITS}/chibi-direction-marksman.png`), 9, 2);
  at(await load(`${UNITS}/chibi-direction-fighter.png`), 10, 1);
  labels.push({
    text: "Board mock at 1x: Cult city, faded Sawmill, Workshop and Market, the five cultists, an Imp, a Horror and a Gibbering Mass; Undead Necromancer and Skeleton; Human Fighters, Knight and Marksman on Grass",
    left: 8,
    top: s3Top,
    size: 13,
    fill: "#a9b0b8",
  });
  blit(canvas, board, 8, s3Top + 22);
  labels.push({
    text: "The same board x2",
    left: 8,
    top: s3Top + 22 + boardRows * CELL + 16,
    size: 13,
    fill: "#a9b0b8",
  });
  blit(canvas, board, 8, s3Top + 22 + boardRows * CELL + 16 + 22, 2);
  await writeSheet(path.resolve(ROOT, out), canvas, labels);
}

/** Every run's samples in rows under the round-1 set, at 1x and x2. */
async function compare(runs: readonly string[], out: string): Promise<void> {
  const bog = await bogTiles();
  const rows: { label: string; sprites: RgbaRaster[] }[] = [
    { label: "Round 1", sprites: await beforeSprites() },
  ];
  for (const run of runs)
    rows.push({ label: path.basename(run), sprites: await newSprites(run) });
  const labelW = 90;
  const left1 = labelW;
  const left2 = labelW + ROBED_ROLES.length * CELL + 24;
  const rowH = CELL * 2 + 8;
  const top = 30;
  const canvas = blank(
    left2 + ROBED_ROLES.length * CELL * 2 + 8,
    top + rows.length * rowH + 8,
    BG,
  );
  const labels: Label[] = [
    {
      text: "Robed cultists: round 1 and the round-2 variants, 1x (left) and x2 (right), on the bog",
      left: 8,
      top: 6,
      size: 14,
    },
  ];
  rows.forEach((row, r) => {
    const y = top + r * rowH;
    labels.push({ text: row.label, left: 8, top: y + CELL - 8, size: 13 });
    row.sprites.forEach((sprite, k) => {
      const tile = bog[(k + r) % 6] as RgbaRaster;
      blit(canvas, tile, left1 + k * CELL, y + CELL);
      place(canvas, sprite, left1 + k * CELL, y + CELL, 1);
      blit(canvas, tile, left2 + k * CELL * 2, y, 2);
      place(canvas, sprite, left2 + k * CELL * 2, y, 2);
    });
  });
  await writeSheet(path.resolve(ROOT, out), canvas, labels);
}

async function main(): Promise<void> {
  const command = process.argv[2];
  const out = required("--out");
  if (command === "compare") {
    await compare(
      process.argv.slice(3).filter((arg, index, all) => {
        const previous = all[index - 1];
        return (
          !arg.startsWith("--") && previous !== "--out" && previous !== "--run"
        );
      }),
      out,
    );
    return;
  }
  if (command === "sheet") {
    const run = process.argv.includes("--production")
      ? undefined
      : required("--run");
    await sheet(run, option("--title") ?? run ?? "Production", out);
    return;
  }
  if (command === "candidates") {
    await candidates(required("--run"), out);
    return;
  }
  throw new Error(
    "usage: review.ts candidates|sheet|compare (--run DIR | --production) --out FILE",
  );
}

main().catch((error: unknown) => {
  process.stderr.write(
    `${error instanceof Error ? error.message : String(error)}\n`,
  );
  process.exitCode = 1;
});
